# New-style (listen-first, hands-on) lessons for Algebra 1, Biology, World History.
# Each level: watch = [[say, caption, visual]], explore = {...}, words = [[parts], [meanings], say, summary],
#             beat = [lines], play = [items]. Captions use *word* for highlight.
# Visuals: {"e":[emoji...]} | {"cell":[parts],"glow":p} | {"g":{lines,quad,pts,tri},"eq":[m,b]} | {"bal":[left,right],"act":..,"win":1}
#          {"tl":k or [k..]} (uses level "tl") | {"pun":[a,b],"fill":0/1} | {"chain":[[emoji,label]..],"hi":k} | {"dna":"ATGC","hi":"A","mut":i}
#          {"pyr":[[emoji,label]..]} | {"nl":{"v":3,"op":">"}} | {"big":[lines]} | {"mach":{"rule":..,"in":..,"out":..}} | {"acr":[words],"hi":k}
#          {"moths":{"bark":"light|dark","l":6,"d":2,"bird":1}}
# Play items: tap(cell) tf sort match seq pick mc build pickline ydot balance dna pun tltap

A = ["membrane", "nucleus", "mito", "ribo"]; PL = ["wall", "membrane", "vacuole", "nucleus", "mito", "ribo", "chloro"]
def W(*lines): return [list(l) for l in lines]
def tf(say, cap, ans, why, vis=None): d = {"t": "tf", "say": say, "cap": cap, "ans": ans, "why": why}; d.update({"vis": vis} if vis else {}); return d
def sort(say, cap, bins, items): return {"t": "sort", "say": say, "cap": cap, "bins": bins, "items": items}
def match(say, cap, pairs): return {"t": "match", "say": say, "cap": cap, "pairs": pairs}
def seq(say, cap, items): return {"t": "seq", "say": say, "cap": cap, "items": items}
def pick(say, cap, opts, why, vis=None): d = {"t": "pick", "say": say, "cap": cap, "opts": opts, "why": why}; d.update({"vis": vis} if vis else {}); return d
def mc(say, cap, opts, why, vis=None): d = {"t": "mc", "say": say, "cap": cap, "opts": opts, "why": why}; d.update({"vis": vis} if vis else {}); return d
def tap(say, cap, cell, target): return {"t": "tap", "say": say, "cap": cap, "cell": cell, "target": target}
def bal(say, cap, start, steps, choices): return {"t": "balance", "say": say, "cap": cap, "start": start, "steps": steps, "choices": choices}
def tltap(say, cap, ans, why): return {"t": "tltap", "say": say, "cap": cap, "ans": ans, "why": why}
